from typing import List, Optional


def max_window_sum(nums: List[int], k: int) -> Optional[int]:
    if k < 1 or k > len(nums):
        return None
    window = sum(nums[:k])
    best = window
    for i in range(k, len(nums)):
        window += nums[i] - nums[i - k]
        best = max(best, window)
    return best

