def count_target_pairs_sorted(nums: List[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    count = 0
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s == target:
            count += 1
            lo += 1
            hi -= 1
        elif s < target:
            lo += 1
        else:
            hi -= 1
    return count

