def window_averages(nums: List[float], k: int) -> List[float]:
    if k < 1 or k > len(nums):
        return []
    window = sum(nums[:k])
    result = [window / k]
    for i in range(k, len(nums)):
        window += nums[i] - nums[i - k]
        result.append(window / k)
    return result

