def count_windows_meeting_average(nums: List[int], k: int, threshold: float) -> int:
    if k < 1 or k > len(nums):
        return 0
    need = threshold * k
    window = sum(nums[:k])
    count = 1 if window >= need else 0
    for i in range(k, len(nums)):
        window += nums[i] - nums[i - k]
        if window >= need:
            count += 1
    return count

