def split_around_pivot(nums: List[int], pivot: int) -> Tuple[List[int], List[int], List[int]]:
    less: List[int] = []
    equal: List[int] = []
    greater: List[int] = []
    for x in nums:
        if x < pivot:
            less.append(x)
        elif x == pivot:
            equal.append(x)
        else:
            greater.append(x)
    return less, equal, greater

