def pair_sum_nearest_target(nums: List[int], target: int) -> int:
    values = sorted(nums)
    lo, hi = 0, len(values) - 1
    best = values[lo] + values[hi]
    while lo < hi:
        s = values[lo] + values[hi]
        if abs(s - target) < abs(best - target) or (
            abs(s - target) == abs(best - target) and s < best
        ):
            best = s
        if s < target:
            lo += 1
        elif s > target:
            hi -= 1
        else:
            return s
    return best

