def count_triples_under_sum(nums: List[int], limit: int) -> int:
    values = sorted(nums)
    n = len(values)
    count = 0
    for first in range(n - 2):
        lo, hi = first + 1, n - 1
        while lo < hi:
            if values[first] + values[lo] + values[hi] < limit:
                count += hi - lo
                lo += 1
            else:
                hi -= 1
    return count

