def window_maximums(nums: List[int], k: int) -> List[int]:
    if k < 1 or k > len(nums):
        return []
    candidates: deque = deque()
    result: List[int] = []
    for i, x in enumerate(nums):
        while candidates and nums[candidates[-1]] <= x:
            candidates.pop()
        candidates.append(i)
        if candidates[0] <= i - k:
            candidates.popleft()
        if i >= k - 1:
            result.append(nums[candidates[0]])
    return result

