def longest_peak_span(heights: List[int]) -> int:
    n = len(heights)
    best = 0
    i = 1
    while i < n - 1:
        if heights[i - 1] < heights[i] > heights[i + 1]:
            left = i - 1
            while left > 0 and heights[left - 1] < heights[left]:
                left -= 1
            right = i + 1
            while right < n - 1 and heights[right] > heights[right + 1]:
                right += 1
            best = max(best, right - left + 1)
            i = right
        else:
            i += 1
    return best

