def shortest_run_at_least_signed(nums: List[int], target: int) -> int:
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    best = len(nums) + 1
    starts: deque = deque()
    for j, pj in enumerate(prefix):
        while starts and pj - prefix[starts[0]] >= target:
            best = min(best, j - starts.popleft())
        while starts and prefix[starts[-1]] >= pj:
            starts.pop()
        starts.append(j)
    return best if best <= len(nums) else -1

